import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonAvatarProps {
  className?: string;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  shape?: 'circle' | 'square';
}

const sizeClasses = {
  sm: 'h-8 w-8',
  md: 'h-12 w-12',
  lg: 'h-16 w-16',
  xl: 'h-24 w-24',
};

export function SkeletonAvatar({ className, size = 'md', shape = 'circle' }: SkeletonAvatarProps) {
  return (
    <Skeleton
      className={cn(
        sizeClasses[size],
        shape === 'circle' ? 'rounded-full' : 'rounded-md',
        className
      )}
    />
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonBadgeProps {
  className?: string;
  size?: 'sm' | 'md' | 'lg';
}

const sizeClasses = {
  sm: 'h-5 w-12',
  md: 'h-6 w-16',
  lg: 'h-7 w-20',
};

export function SkeletonBadge({ className, size = 'md' }: SkeletonBadgeProps) {
  return <Skeleton className={cn('rounded-full', sizeClasses[size], className)} />;
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonBreadcrumbProps {
  className?: string;
  items?: number;
}

export function SkeletonBreadcrumb({ className, items = 3 }: SkeletonBreadcrumbProps) {
  return (
    <div className={cn('flex items-center gap-2', className)}>
      {Array.from({ length: items }).map((_, i) => (
        <div key={i} className="flex items-center gap-2">
          <Skeleton className="h-4 w-16" />
          {i < items - 1 && <Skeleton className="h-4 w-4" />}
        </div>
      ))}
    </div>
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonButtonProps {
  className?: string;
  size?: 'sm' | 'md' | 'lg';
  variant?: 'default' | 'icon';
}

const sizeClasses = {
  sm: 'h-8 w-20',
  md: 'h-10 w-24',
  lg: 'h-11 w-28',
};

const iconSizeClasses = {
  sm: 'h-8 w-8',
  md: 'h-10 w-10',
  lg: 'h-11 w-11',
};

export function SkeletonButton({
  className,
  size = 'md',
  variant = 'default',
}: SkeletonButtonProps) {
  return (
    <Skeleton
      className={cn(
        'rounded-md',
        variant === 'icon' ? iconSizeClasses[size] : sizeClasses[size],
        className
      )}
    />
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonCardProps {
  className?: string;
  showImage?: boolean;
  showHeader?: boolean;
  showDescription?: boolean;
  showFooter?: boolean;
  lines?: number;
}

export function SkeletonCard({
  className,
  showImage = true,
  showHeader = true,
  showDescription = true,
  showFooter = true,
  lines = 3,
}: SkeletonCardProps) {
  return (
    <div className={cn('space-y-4 rounded-lg border border-border bg-card p-4', className)}>
      {showImage && <Skeleton className="h-48 w-full rounded-md" />}

      <div className="space-y-3">
        {showHeader && <Skeleton className="h-6 w-3/4" />}

        {showDescription && (
          <div className="space-y-2">
            {Array.from({ length: lines }).map((_, i) => (
              <Skeleton key={i} className={cn('h-4', i === lines - 1 ? 'w-2/3' : 'w-full')} />
            ))}
          </div>
        )}
      </div>

      {showFooter && (
        <div className="flex gap-2 pt-2">
          <Skeleton className="h-9 w-20" />
          <Skeleton className="h-9 w-20" />
        </div>
      )}
    </div>
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonCarouselProps {
  className?: string;
  items?: number;
  showControls?: boolean;
  showIndicators?: boolean;
  aspectRatio?: 'square' | 'video' | 'wide';
}

const aspectRatioClasses = {
  square: 'aspect-square',
  video: 'aspect-video',
  wide: 'aspect-[21/9]',
};

export function SkeletonCarousel({
  className,
  items = 3,
  showControls = true,
  showIndicators = true,
  aspectRatio = 'video',
}: SkeletonCarouselProps) {
  return (
    <div className={cn('space-y-4', className)}>
      {/* Carousel Container */}
      <div className="relative overflow-hidden rounded-lg">
        <Skeleton className={cn('w-full', aspectRatioClasses[aspectRatio])} />

        {/* Navigation Controls */}
        {showControls && (
          <>
            <Skeleton className="absolute top-1/2 left-4 h-10 w-10 -translate-y-1/2 rounded-full" />
            <Skeleton className="absolute top-1/2 right-4 h-10 w-10 -translate-y-1/2 rounded-full" />
          </>
        )}
      </div>

      {/* Indicators */}
      {showIndicators && (
        <div className="flex justify-center gap-2">
          {Array.from({ length: items }).map((_, i) => (
            <Skeleton key={i} className="h-2 w-8 rounded-full" />
          ))}
        </div>
      )}
    </div>
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonChartProps {
  className?: string;
  type?: 'bar' | 'line' | 'pie' | 'area';
  showLegend?: boolean;
  showTitle?: boolean;
  chartHeight?: string;
}

export function SkeletonChart({
  className,
  type = 'bar',
  showLegend = true,
  showTitle = true,
  chartHeight = 'h-[280px]',
}: SkeletonChartProps) {
  return (
    <div className={cn('space-y-2', className)}>
      {showTitle && (
        <div className="space-y-2">
          <Skeleton className="h-5 w-32" />
          <Skeleton className="h-4 w-64" />
        </div>
      )}

      <div className="space-y-4">
        {type === 'bar' && (
          <div className={cn('flex items-end justify-between gap-2', chartHeight)}>
            {Array.from({ length: 8 }).map((_, i) => (
              <Skeleton
                key={i}
                className="w-full"
                style={{ height: `${Math.random() * 60 + 40}%` }}
              />
            ))}
          </div>
        )}

        {type === 'line' && (
          <div className={cn('relative', chartHeight)}>
            <Skeleton className="absolute inset-0 rounded-lg" />
            <div className="absolute inset-0 flex items-center justify-center p-4">
              <svg className="h-full w-full opacity-10" viewBox="0 0 100 50">
                <polyline
                  points="0,40 20,30 40,35 60,15 80,20 100,10"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                />
                <polyline
                  points="0,45 20,35 40,40 60,20 80,25 100,15"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="2"
                  opacity="0.5"
                />
              </svg>
            </div>
          </div>
        )}

        {type === 'pie' && (
          <div className={cn('flex items-center justify-center', chartHeight)}>
            <Skeleton className="h-48 w-48 rounded-full" />
          </div>
        )}

        {type === 'area' && (
          <div className={cn('relative', chartHeight)}>
            <Skeleton className="absolute inset-0 rounded-lg" />
            <div className="absolute inset-0 flex items-end p-4">
              <svg className="h-full w-full opacity-20" viewBox="0 0 100 50">
                <polygon
                  points="0,50 0,40 20,30 40,35 60,15 80,20 100,10 100,50"
                  fill="currentColor"
                  opacity="0.3"
                />
              </svg>
            </div>
          </div>
        )}

        {showLegend && (
          <div className="flex flex-wrap justify-center gap-4 border-border border-t pt-4">
            {Array.from({ length: 2 }).map((_, i) => (
              <div key={i} className="flex items-center gap-2">
                <Skeleton className="h-3 w-3 rounded-full" />
                <Skeleton className="h-4 w-24" />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonDataCardProps {
  className?: string;
  showIcon?: boolean;
  showTrend?: boolean;
}

export function SkeletonDataCard({
