import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonTableProps {
  className?: string;
  rows?: number;
  columns?: number;
  showHeader?: boolean;
  showPagination?: boolean;
}

export function SkeletonTable({
  className,
  rows = 5,
  columns = 4,
  showHeader = true,
  showPagination = true,
}: SkeletonTableProps) {
  return (
    <div className={cn('space-y-4', className)}>
      <div className="rounded-md border border-border">
        <div className="overflow-hidden">
          {/* Header */}
          {showHeader && (
            <div
              className="grid gap-4 border-border border-b bg-muted/50 p-4"
              style={{ gridTemplateColumns: `repeat(${columns}, 1fr)` }}
            >
              {Array.from({ length: columns }).map((_, i) => (
                <Skeleton key={i} className="h-5 w-full" />
              ))}
            </div>
          )}

          {/* Body */}
          {Array.from({ length: rows }).map((_, rowIndex) => (
            <div
              key={rowIndex}
              className="grid gap-4 border-border border-b p-4 last:border-0"
              style={{ gridTemplateColumns: `repeat(${columns}, 1fr)` }}
            >
              {Array.from({ length: columns }).map((_, colIndex) => (
                <Skeleton key={colIndex} className="h-4 w-full" />
              ))}
            </div>
          ))}
        </div>
      </div>

      {/* Pagination */}
      {showPagination && (
        <div className="flex items-center justify-between">
          <Skeleton className="h-9 w-32" />
          <div className="flex gap-2">
            <Skeleton className="h-9 w-9" />
            <Skeleton className="h-9 w-9" />
            <Skeleton className="h-9 w-9" />
            <Skeleton className="h-9 w-9" />
          </div>
          <Skeleton className="h-9 w-32" />
        </div>
      )}
    </div>
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonTabsProps {
  className?: string;
  tabs?: number;
  showContent?: boolean;
}

export function SkeletonTabs({ className, tabs = 3, showContent = true }: SkeletonTabsProps) {
  return (
    <div className={cn('space-y-4', className)}>
      {/* Tab Headers */}
      <div className="flex gap-2 border-border border-b">
        {Array.from({ length: tabs }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-24 rounded-t-md" />
        ))}
      </div>

      {/* Tab Content */}
      {showContent && (
        <div className="space-y-4 pt-2">
          <Skeleton className="h-6 w-48" />
          <div className="space-y-2">
            <Skeleton className="h-4 w-full" />
            <Skeleton className="h-4 w-full" />
            <Skeleton className="h-4 w-3/4" />
          </div>
        </div>
      )}
    </div>
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonTextProps {
  className?: string;
  lines?: number;
  variant?: 'paragraph' | 'heading' | 'caption';
}

export function SkeletonText({ className, lines = 3, variant = 'paragraph' }: SkeletonTextProps) {
  const heightClass = {
    paragraph: 'h-4',
    heading: 'h-6',
    caption: 'h-3',
  }[variant];

  return (
    <div className={cn('space-y-2', className)}>
      {Array.from({ length: lines }).map((_, i) => (
        <Skeleton key={i} className={cn(heightClass, i === lines - 1 ? 'w-2/3' : 'w-full')} />
      ))}
    </div>
  );
}

import { Skeleton } from '../../ui/feedback/skeleton';
import { cn } from '../../../lib/utils';

interface SkeletonTimelineProps {
  className?: string;
  items?: number;
  showIcon?: boolean;
}

export function SkeletonTimeline({ className, items = 4, showIcon = true }: SkeletonTimelineProps) {
  return (
    <div className={cn('space-y-4', className)}>
      {Array.from({ length: items }).map((_, index) => (
        <div key={index} className="flex gap-4">
          {/* Timeline Icon/Dot */}
          <div className="flex flex-col items-center">
            {showIcon ? (
              <Skeleton className="h-8 w-8 shrink-0 rounded-full" />
            ) : (
              <Skeleton className="h-3 w-3 shrink-0 rounded-full" />
            )}
            {index < items - 1 && <div className="mt-2 h-full min-h-16 w-px bg-border" />}
          </div>

          {/* Timeline Content */}
          <div className="flex-1 space-y-2 pb-8">
            <Skeleton className="h-5 w-32" />
            <Skeleton className="h-4 w-full" />
            <Skeleton className="h-4 w-3/4" />
            <Skeleton className="mt-2 h-3 w-24" />
          </div>
        </div>
      ))}
    </div>
  );
}
